package com.infoviaan.basic.IfElse;

public class CheckNumberIsPositiveOrNegative {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n = -25;
		
		if(n > 0) {
			System.out.println("Entred Number is Positive");
		} else {
			System.out.println("Entred Number is Negative");
		}
	}

}
